<?php $data=cart_details();$items=$data['items'];$subtotal=$data['subtotal'];?><section class="page-heading compact"><div class="container"><span class="eyebrow">ALMOST TOO GOOD TO SHARE</span><h1>Your <em>bag.</em></h1></div></section><section class="container section"><div class="cart-layout"><div><?php if(!$items):?><div class="empty-state"><span>♡</span><h2>It's a little empty in here</h2><p>Let's fill your bag with something delicious.</p><a class="btn btn-primary" href="<?=h(url('shop'))?>">Shop the menu ↗</a></div><?php else:?><?php foreach($items as $i):?><div class="cart-item"><img src="<?=h(slug_image($i['image_key']))?>" alt="<?=h($i['name'])?>"><div class="cart-item-main"><h3><?=h($i['name'])?></h3><small><?=h($i['short_description'])?></small><form method="post" class="cart-qty" action="<?=h(url('cart'))?>"><?=csrf_input()?><input type="hidden" name="action" value="cart_update"><input type="hidden" name="id" value="<?=intval($i['id'])?>"><label>Qty <input type="number" name="qty" value="<?=intval($i['qty'])?>" min="0" max="20"></label><button class="small-btn" type="submit">Update</button><button class="small-btn remove" type="submit" name="qty" value="0">Remove</button></form></div><strong><?=h(money($i['line_total']))?></strong></div><?php endforeach;?><?php endif;?></div><aside class="summary-card"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><strong><?=h(money($subtotal))?></strong></div><div class="summary-line"><span>Delivery</span><span>Calculated at checkout</span></div><hr><div class="summary-line total"><span>Subtotal</span><strong><?=h(money($subtotal))?></strong></div><p class="micro">Free delivery on orders over 25 JOD. Pickup is free.</p><?php if($items):?><a class="btn btn-primary full" href="<?=h(url('checkout'))?>">Continue to checkout ↗</a><?php else:?><a class="btn btn-secondary full" href="<?=h(url('shop'))?>">Explore menu</a><?php endif;?></aside></div></section>
